from pathlib import Path

core = Path("core/core-rule-full.md")
s = core.read_text(encoding="utf-8")

old = """この技能は、「敵戦闘集団」が撤退した場合にも１度だけ使用することができます。  
成功した場合、その敵兵を捕虜とします。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
"""
new = """この技能は、「敵戦闘集団」が撤退した場合にも１度だけ使用することができます。  
成功した場合、その敵兵を捕虜とします。  
有人の高脅威目標の生命点が1になった時点で、その高脅威目標の撤退条件も同時に成立した場合は、撤退を処理する直前に【ネゴシエーション】を1度だけ使用できます。成功した場合は通常どおり【捕虜】または【鹵獲】として処理し、その対象の撤退は発生しません。失敗した場合は、そのまま撤退を処理します。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
"""
if s.count(old) != 1:
    raise SystemExit(f"core negotiation anchor count={s.count(old)}")
s = s.replace(old, new, 1)
core.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 54. Core【ネゴシエーション】と高脅威目標の撤退競合 — 採用済み"
section = """

## 54. Core【ネゴシエーション】と高脅威目標の撤退競合 — 採用済み

ユーザー承認により、有人の高脅威目標が生命点1になった時点でシナリオ固有の撤退条件も同時に成立する場合の処理順をCore v1.01へ追加する。

- 対象が意思疎通可能な有人の高脅威目標であり、生命点1になったことで【ネゴシエーション】の使用条件と撤退条件が同時に成立した場合、撤退処理の直前に【ネゴシエーション】を1度だけ使用できる。
- 成功した場合、人物は【捕虜】、有人車両・有人固定兵装は乗員・操作員を【捕虜】として装備を【鹵獲】し、その対象の撤退は発生しない。
- 失敗した場合は、そのままシナリオ固有の撤退を処理する。
- 狂信的な敵、任務遂行のみを目的とする敵、無人対象など、Coreまたはシナリオによって【ネゴシエーション】対象外となる相手にはこの割り込み機会も発生しない。
- 既存の「敵戦闘集団が撤退した場合にも1度だけ使用できる」規定は維持し、高脅威目標については撤退直前に処理することで捕虜・鹵獲と撤退の競合を解消する。
- Black Sun出目62【屋上の影】では、反応【敵対的】時に生命点2から1へ減少すると撤退条件と【ネゴシエーション】条件が同時成立するため、このCore共通規定を適用する。

これにより、撤退条件を持つ有人高脅威目標でもHP1で交渉を試みる余地を残しつつ、失敗時には既定の撤退が確実に進行する。シナリオ側に個別の処理順を重複記載する必要もなくなる。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
